"""Evaluation labels are an independent oracle, never generated by the scanner."""
import hashlib
import json

import pytest

from scripts import evaluate_source
from scripts.evaluate_source import FIXTURES, evaluate_corpus, score_occurrences


def item(line=1, **kwargs):
    return dict(file="sample.py", line=line, algorithm="AES", usage="encryption", **kwargs)


def test_occurrence_multisets_keep_duplicates_and_separate_parameter_accuracy():
    expected = [item(parameters={"key_bits": 256}), item(parameters={"key_bits": 128}), item(2)]
    actual = [item(parameters={"key_bits": 128}), item(parameters={"key_bits": 192}), item(3)]
    result = score_occurrences(expected, actual)
    assert result["detection"] == dict(true_positive=2, false_positive=1, false_negative=1,
                                      expected_occurrences=3, actual_occurrences=3,
                                      precision=2/3, recall=2/3)
    assert result["parameters"]["correct_occurrences"] == 1
    assert result["parameters"]["field_accuracy"] == 0.5


def test_duplicate_parameter_matching_is_order_independent():
    expected = [item(parameters={"mode": "GCM"}), item(parameters={"mode": "GCM", "key_bits": 256})]
    actual = [item(parameters={"mode": "GCM", "key_bits": 256}), item(parameters={"mode": "GCM", "key_bits": 128})]
    assert score_occurrences(expected, actual)["parameters"]["correct_occurrences"] == 2
    assert score_occurrences(expected[::-1], actual[::-1])["parameters"]["correct_occurrences"] == 2


def test_unknown_parameter_is_a_label_and_known_gaps_remain_in_denominator():
    result = score_occurrences([item(parameters={"key_bits": None}),
                                item(2, known_gap="custom primitive")],
                               [item(parameters={"key_bits": 256})])
    assert result["detection"]["recall"] == 0.5
    assert result["supported_subset"]["recall"] == 1
    assert result["parameters"]["correct_occurrences"] == 0
    assert result["false_negatives"][0]["known_gap"] == "custom primitive"


def test_empty_scores_are_undefined_not_perfect():
    result = score_occurrences([], [])
    assert result["detection"]["precision"] is None
    assert result["detection"]["recall"] is None
    assert result["parameters"]["field_accuracy"] is None


def test_holdout_content_hashes_and_positive_negative_unknown_partitions():
    manifest = json.loads((FIXTURES / "holdout-labels.json").read_text())
    assert len(manifest["files"]) == 9
    for entry in manifest["files"]:
        raw = (FIXTURES / "holdout" / entry["path"]).read_bytes()
        assert hashlib.sha256(raw).hexdigest() == entry["sha256"]
        assert bool(entry["expected"]) == (not entry["path"].lower().startswith("negative"))


def test_organizer_manifest_has_all_24_files_and_explicit_semantic_gaps():
    manifest = json.loads((FIXTURES / "organizer-labels.json").read_text())
    assert len(manifest["files"]) == 24
    assert manifest["commit"] == "39e8f18dcfb5edc66eda0f47bb44884aa7db5c9c"
    labels = [label for entry in manifest["files"] for label in entry["expected"]]
    assert len(labels) == 52
    assert {label["algorithm"] for label in labels if label.get("known_gap")} == {"AES", "PBKDF2", "RSA"}


def test_evaluation_refuses_changed_corpus(tmp_path):
    manifest = {"schema_version": 1, "corpus": "test", "files": [
        {"path": "example.py", "sha256": "0" * 64, "expected": []}]}
    (tmp_path / "example.py").write_text("import hashlib\n")
    manifest_path = tmp_path / "labels.json"
    manifest_path.write_text(json.dumps(manifest))
    with pytest.raises(ValueError, match="hash mismatch"):
        evaluate_corpus(tmp_path, manifest_path)


def test_holdout_scans_successfully_against_manual_labels():
    report = evaluate_corpus(FIXTURES / "holdout", FIXTURES / "holdout-labels.json")
    assert report["files"] == report["assessed_files"] == 9
    assert not report["scan_errors"]
    assert report["detection"]["false_positive"] == 0, report["false_positives"]
    assert report["detection"]["false_negative"] == 0, report["false_negatives"]
    assert not report["parameters"]["mismatches"]


@pytest.mark.parametrize("expected,actual,errors", [
    ([item()], [item(), item(2)], []),
    ([item(), item(2)], [item()], []),
    ([item(parameters={"key_bits": None})], [item(parameters={"key_bits": 256})], []),
    ([item(known_gap="unsupported construction")], [], []),
    ([item()], [item()], [{"code": "scan_failed"}]),
])
def test_strict_cli_fails_on_accuracy_regressions_and_preserves_report(monkeypatch, capsys, expected, actual, errors):
    report = {"scan_errors": errors, **score_occurrences(expected, actual)}
    monkeypatch.setattr(evaluate_source, "evaluate_corpus", lambda *_: report)
    assert evaluate_source.main(["--strict"]) == 1
    assert json.loads(capsys.readouterr().out)["reports"] == [report]
    # Non-strict mode remains useful for measuring incomplete implementations.
    assert evaluate_source.main([]) == int(bool(errors))
    assert json.loads(capsys.readouterr().out)["reports"] == [report]


def test_strict_cli_checks_optional_organizer_report_as_well(monkeypatch, capsys, tmp_path):
    perfect = {"scan_errors": [], **score_occurrences([item()], [item()])}
    regression = {"scan_errors": [], **score_occurrences([item()], [])}
    monkeypatch.setattr(evaluate_source, "evaluate_corpus", lambda root, _: regression if root == tmp_path else perfect)
    assert evaluate_source.main(["--strict"]) == 0
    assert json.loads(capsys.readouterr().out)["reports"] == [perfect]
    assert evaluate_source.main(["--strict", "--organizer-root", str(tmp_path)]) == 1
    assert json.loads(capsys.readouterr().out)["reports"] == [perfect, regression]
